//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징


scwin.vScrenID = "ULDINS30900.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_1);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
    var array_grid = [grd_List];
    setResizeGrid(array_grid);
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {
    ins_combo_set(dts_STD_CD_APPL_CONTN_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03425", "ALL"); //상품구분 		
    ins_combo_set(dts_APPL_PROCS_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03398", "ALL"); //처리구분 		

};


/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var sToday = $c.ut.cGetToday2();
    edt_FROM_STD_CD_APPL_DD.setValue(sToday);
    edt_TO_STD_CD_APPL_DD.setValue(sToday);
    $c.stf.showObj(panel_5, false);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_List.removeAll();
    txb_TotalCnt.setValue("총 0건");
};


/**
 * 조회
 */
scwin.ins_search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdReceiptListInquiry" + "&outputMessageId=INS_LIST_STDCD_RECEIPT_LIST_INQUIRY" + "&param01=" + $c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD) + "&param02=" + $c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD) + "&param03=" + $c.stf.getObjectValue(cmb_STD_CD_APPL_CONTN_TP_CD) + "&param04=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&param05=" + $c.stf.getObjectValue(cmb_APPL_PROCS_TP_CD) + "&param06=" + $c.stf.getObjectValue(txb_ISU_NM) + "&param07=" + $c.stf.getObjectValue(txb_APCT_NM) + "&param08=" + $c.stf.getObjectValue(txb_APPL_COM_NM) + "&param09=" + $c.stf.getObjectValue(edt_FROM_ACPT_PROCS_DD) + "&param10=" + $c.stf.getObjectValue(edt_TO_ACPT_PROCS_DD);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function() {
    //발행기관코드가 입력되면 기간조건 체크안함
    if (txb_ISUR_CD.getValue() == "") {
        //날짜입력체크
        if ($c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD) == "" && $c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD) == "" && $c.stf.getObjectValue(edt_FROM_ACPT_PROCS_DD) == "" && $c.stf.getObjectValue(edt_TO_ACPT_PROCS_DD) == "") {
            //날짜입력이없으면
            $c.win.alert("신청일 또는 처리일을 입력하세요.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        } else {
            if ($c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD) != "" || $c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD) != "") {
                if ($c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD) == "" || $c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD) == "") {
                    $c.win.alert("신청일을 입력하세요.");
                    edt_FROM_STD_CD_APPL_DD.focus();
                    return false;
                }
            }
            if ($c.stf.getObjectValue(edt_FROM_ACPT_PROCS_DD) != "" || $c.stf.getObjectValue(edt_TO_ACPT_PROCS_DD) != "") {
                if ($c.stf.getObjectValue(edt_FROM_ACPT_PROCS_DD) == "" || $c.stf.getObjectValue(edt_TO_ACPT_PROCS_DD) == "") {
                    $c.win.alert("처리일을 입력하세요.");
                    edt_FROM_ACPT_PROCS_DD.focus();
                    return false;
                }
            }
        }

        // 1년 이내 체크
        if (($c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD) != "" && $c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD) != "") &&
            eval($c.ut.cGetPlusYear(edt_FROM_STD_CD_APPL_DD.getValue(), 1)) < eval(edt_TO_STD_CD_APPL_DD.getValue())) {
            $c.win.alert("신청일의 검색 기간은 1년 이내로만 가능합니다.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        }
        if (($c.stf.getObjectValue(edt_FROM_ACPT_PROCS_DD) != "" && $c.stf.getObjectValue(edt_TO_ACPT_PROCS_DD) != "") &&
            eval($c.ut.cGetPlusYear(edt_FROM_ACPT_PROCS_DD.getValue(), 1)) < eval(edt_TO_ACPT_PROCS_DD.getValue())) {
            $c.win.alert("처리일의 검색 기간은 1년 이내로만 가능합니다.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        }
    }

    // 신청일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_APPL_DD, edt_TO_STD_CD_APPL_DD) == false) {
        return false;
    }
    // 처리일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_ACPT_PROCS_DD, edt_TO_ACPT_PROCS_DD) == false) {
        return false;
    }
    return true;
};


/**
 * 발생기관 팝업에서 값 받음.
 */
scwin.fn_GetParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue();
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.gform_onload = function() {
    scwin.fn_Init();
    txb_ISU_NM.focus();
};
scwin.txb_ISUR_CD_onchange = function() {
    //txb_ISUR_NM.value = "";

};
scwin.img_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.img_FROM_STD_CD_APPL_DD_onclick = function() {
    popUpCalendar2(edt_FROM_STD_CD_APPL_DD);
};
scwin.img_TO_STD_CD_APPL_DD_onclick = function() {
    popUpCalendar2(edt_TO_STD_CD_APPL_DD);
};
scwin.img_FROM_ACPT_PROCS_DD_onclick = function() {
    popUpCalendar2(edt_FROM_ACPT_PROCS_DD);
};
scwin.img_TO_ACPT_PROCS_DD_onclick = function() {
    popUpCalendar2(edt_TO_ACPT_PROCS_DD);
};
scwin.dts_List_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_List);
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_List);
    txb_TotalCnt.setValue("총 " + rowcount + "건");
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (row == 0) return;
    if (colid == "ISU_NM" || colid == "STD_CD_APPL_ID") {
        var sStdCd = dts_List.getCellData(row, "STD_CD_APPL_ID"); // STD_CD_APPL_ID 

        if (sStdCd != "") {
            var KND = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_CD");
            var STD_CD = dts_List.getCellData(row, "STD_CD");
            //alert("STD_CD " +STD_CD);
            if (KND == "지표" || KND == "선물옵션" || KND == "스트립") {
                txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
            } else {
                txb_param1.setValue(dts_List.getCellData(row, "STD_CD_APPL_ID"));
            }
            txb_param2.setValue("R");
            fn_GetPar = fn_GetParam;
            ins_ViewIsuReqInfo(KND);
        }
    } else if (colid == "STD_CD") {
        var sStdCd = dts_List.getCellData(row, "STD_CD"); // 표준코드 

        if (sStdCd != "") {
            var KND = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_NM");
            var STD_CD_APPL_CONTN_TP_CD = dts_List.getCellData(row, "STD_CD_APPL_CONTN_TP_CD");
            if (STD_CD_APPL_CONTN_TP_CD == "77") {
                KND = "전자단기사채";
            }
            var STD_CD = dts_List.getCellData(row, "STD_CD");
            //alert("STD_CD " +STD_CD);
            if (KND == "지표" || KND == "선물옵션" || KND == "스트립") {
                txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
            } else {
                txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
            }
            txb_param2.setValue("");
            fn_GetPar = fn_GetParam;
            ins_ViewIsuMaster(KND, STD_CD);
        }
    } else if (colid == "COM_NM") {
        var isurcd = dts_List.getCellData(row, "ISUR_CD").substring(0, 1);
        if (isurcd == "#") return;
        txb_param1.setValue(dts_List.getCellData(row, "ISUR_CD")); // 발행기관 코드 
        txb_param2.setValue(dts_List.getCellData(row, "COM_NM")); // 발행기관명  
        fn_GetPar = fn_GetParam;
        ins_popupOpen("", "", "ULDINS91600", "발행기관 상세정보", "1190", "710");
    }
};
scwin.txb_ISU_NM_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_ISU_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        }
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_ISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        }
    }
};
scwin.cmb_STD_CD_APPL_CONTN_TP_CD_OnSelChange = function() {
    scwin.ins_search();
};
scwin.cmb_APPL_PROCS_TP_CD_OnSelChange = function() {
    scwin.ins_search();
};
scwin.img_BND_CLSS_CD_ERASER_onclick = function() {
    txb_ISUR_CD.setValue("");
    txb_ISUR_NM.setValue("");
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var title = "표준코드처리내역";
    var xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";
    $c.data.downloadGridViewOffice(grd_List, title, xls_path, 8, 0);
    //grd_List.GridToExcel(title, "", "8");

};
